import "dart:convert";
import "dart:typed_data";
import "package:flutter/material.dart";

const String _kNobackPreviewLogoBase64 = "";

final Uint8List _kNobackPreviewLogoBytes = base64Decode(_kNobackPreviewLogoBase64);

/// Resilient brand logo widget for Noback-preview.
/// Displays the Noback-preview brand logo with an embedded
/// fallback so it renders immediately even before a full app rebuild.
class AppBrandLogo extends StatelessWidget {
  final double? width;
  final double? height;
  final BoxFit fit;

  const AppBrandLogo({
    super.key,
    this.width,
    this.height,
    this.fit = BoxFit.contain,
  });

  @override
  Widget build(BuildContext context) {
    return Image.asset(
      "assets/images/Noback-preview.png",
      width: width,
      height: height,
      fit: fit,
      errorBuilder: (context, error, stackTrace) {
        return Image.memory(
          _kNobackPreviewLogoBytes,
          width: width,
          height: height,
          fit: fit,
        );
      },
    );
  }
}
